-- Install Marvel/hero costumes generated by costume-tools/build_marvel_costumes.py
SET NAMES utf8mb4;
START TRANSACTION;

DELETE FROM item_shop_option WHERE item_shop_id IN (SELECT id FROM item_shop WHERE tab_id = 1120 AND temp_id IN (2077));
DELETE FROM item_shop WHERE tab_id = 1120 AND temp_id IN (2077);
DELETE FROM item_default_option WHERE item_template_id IN (2077);
DELETE FROM head_avatar WHERE head_id IN (2180, 2181, 2182);
DELETE FROM item_template WHERE id IN (2077);
DELETE FROM part WHERE id IN (2180, 2181, 2182);




DELETE FROM item_default_option WHERE item_template_id IN (2077);


SELECT 1120, 2077, 1, 1, 1, 2000, 0, 0, NOW()
WHERE EXISTS (SELECT 1 FROM tab_shop WHERE id = 1120 AND shop_id = 112)
  AND NOT EXISTS (SELECT 1 FROM item_shop WHERE tab_id = 1120 AND temp_id = 2077);

COMMIT;
